const brandProfile = $('Fetch Brand Profile').first().json;
const template = $('Fetch Overlay Template').first().json;
const webhookBody = $('Webhook').first().json.body;

if (!template || !template.id) throw new Error('Overlay template not found: ' + webhookBody.overlayTemplateId);

const brandId = webhookBody.brandId;
const logoUrl = brandProfile.logo_url || null;
const rawBrandStyle = brandProfile.style_prompt || '';
// Strip clothing-colour directives that trigger gpt-image-2 safety filters
const brandStyle = rawBrandStyle
  .replace(/,?\s*their clothes should not be[^.!?\n]*/gi, '')
  .replace(/,?\s*wearing[^,;.!?\n]*(?:red|black|blue|white|green|yellow|orange|purple|pink)[^,;.!?\n]*/gi, '')
  .trim();
const bgPrompt = template.bg_prompt || '';
const puppeteerConfig = template.puppeteer_config || {};
const copy = webhookBody.copy || {};

if (!bgPrompt) throw new Error('Overlay template has no bg_prompt set');

const copyContext = copy.heading
  ? `\n\nCOPY CONTEXT (use to inform the visual theme and mood only — do NOT render any text in the image):\nHeadline: "${copy.heading}"${copy.microcopy ? `\nMicrocopy: "${copy.microcopy}"` : ''}${copy.subheading ? `\nSubheading: "${copy.subheading}"` : ''}`
  : '';

const prompt = `BACKGROUND IMAGE PROMPT:\n${bgPrompt}${copyContext}\n\nBRAND STYLE (apply these colors and visual elements):\n${brandStyle}\n\nGenerate a professional, clean background image for a 1080x1080 social media post.`;

return [{
  json: {
    brandId,
    logoUrl,
    puppeteerConfig,
    storagePath: `${brandId}/${Date.now()}_bg.png`,
    requestBody: JSON.stringify({
      model: 'gpt-image-2',
      prompt,
      size: '1024x1024',
      quality: 'medium',
      n: 1
    })
  }
}];

const imageResp = $input.first().json;
const meta = $('Build BG Prompt').first().json;

const imageData = imageResp.data && imageResp.data[0];
if (!imageData || !imageData.b64_json) throw new Error('No image data in response: ' + JSON.stringify(imageResp));

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(imageData.b64_json, 'base64'),
  'bg.png',
  'image/png'
);

return [{
  json: {
    brandId: meta.brandId,
    logoUrl: meta.logoUrl,
    puppeteerConfig: meta.puppeteerConfig,
    storagePath: meta.storagePath
  },
  binary: { data: binaryData }
}];

const item = $input.first();
const meta = item.json;
const mime = (item.binary && item.binary.data && item.binary.data.mimeType) || 'image/png';
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileName = (meta.storagePath || meta.fileName || ('upload-' + Date.now() + '.png')).toString().split('/').pop();
const dataUrl = 'data:' + mime + ';base64,' + buffer.toString('base64');

const boundary = '----n8nIkBoundary' + Date.now().toString(36);
const parts = [];
function addField(name, value) {
  parts.push(
    '--' + boundary + '\r\n' +
    'Content-Disposition: form-data; name="' + name + '"\r\n\r\n' +
    value + '\r\n'
  );
}
addField('file', dataUrl);
addField('fileName', fileName);
addField('folder', '/generated-posts');
addField('useUniqueFileName', 'true');
parts.push('--' + boundary + '--\r\n');
const body = parts.join('');

let uploaded;
try {
  uploaded = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://upload.imagekit.io/api/v1/files/upload',
    headers: {
      Authorization: 'Basic __IMAGEKIT_BASIC_AUTH__',
      'Content-Type': 'multipart/form-data; boundary=' + boundary,
    },
    body,
    timeout: 120000,
  });
} catch (err) {
  throw new Error('ImageKit httpRequest failed: ' + (err.message || String(err)));
}

if (typeof uploaded === 'string') {
  try { uploaded = JSON.parse(uploaded); } catch (_) {}
}
if (!uploaded || !uploaded.url) {
  throw new Error('ImageKit upload failed: ' + JSON.stringify(uploaded));
}

return [{ json: Object.assign({}, meta, uploaded) }];

const uploaded = $('Upload BG to ImageKit').first().json;
const meta = $('Extract BG Image').first().json;

const bgImageUrl = uploaded.url;
if (!bgImageUrl) throw new Error('ImageKit upload failed: ' + JSON.stringify(uploaded));

return [{
  json: {
    bgImageUrl,
    logoUrl: meta.logoUrl,
    puppeteerConfig: meta.puppeteerConfig
  }
}];
